#!/usr/bin/env python3
from pathlib import Path
from datetime import datetime
import base64,re,shutil,subprocess,tempfile
PAYLOAD={'public/assets/super-juca-logo.png': '', 'public/encartes/super-juca/pagina-01.jpg': '', 'public/super-juca.css': ''}
root=Path.cwd();p=root/'public/app.js'
if not p.exists():raise SystemExit('Execute na raiz do projeto, junto ao package.json.')
app=p.read_text()
if '// super-juca-card-v1' in app:
    print('Super Juca ja incluido. Nenhuma alteracao repetida.');raise SystemExit(0)
def change(text,old,new):
    if text.count(old)!=1:raise SystemExit('Estrutura diferente da esperada. Nada foi alterado. Envie o public/app.js atualizado.')
    return text.replace(old,new,1)
app=change(app,'for(const store of stores) for(const branch of store.branches||[]) {',"""// super-juca-card-v1
stores.push({
  id:'super-juca',name:'Super Juca',demo:true,
  logo:'/assets/super-juca-logo.png',
  validFrom:'2026-09-18',validUntil:'2026-09-21',
  validityLabel:'Encarte de teste · Ofertas originalmente válidas de 18 a 21/09/2026',
  pages:['/encartes/super-juca/pagina-01.jpg'],
  branches:[
    {label:'Loja 1 · Santo Afonso',neighborhood:'Santo Afonso',address:'Rua Visconde de Araguaia, 331, Santo Afonso - Novo Hamburgo'},
    {label:'Loja 2 · Santo Afonso',neighborhood:'Santo Afonso',address:'Rua Carlos Afonso Braunger, 279, Santo Afonso - Novo Hamburgo'},
    {label:'Industrial',neighborhood:'Industrial',address:'Rua Pinheiro Machado, 415, Industrial - Novo Hamburgo'}
  ]
})
for(const store of stores) for(const branch of store.branches||[]) {""")
app=change(app,"=>store.id==='ofersul'||!store.validFrom||","=>store.demo===true||store.id==='ofersul'||!store.validFrom||")
app=change(app,'${b.neighborhood}</button>','${b.label||b.neighborhood}</button>')
app=change(app,'if(matching>=0)state.branch=matching',"if(matching>=0&&s.branches[state.branch]?.neighborhood!==neighborhood.value)state.branch=matching")
index=root/'public/index.html';html=index.read_text()
html=change(html,'</head>','<link rel="stylesheet" href="/super-juca.css">\n</head>')
swpath=root/'public/sw.js';sw=swpath.read_text()
sw,n=re.subn(r"(const CACHE\s*=\s*['\"])([^'\"]+)",lambda m:m[1]+m[2]+'-super-juca-v1',sw,count=1)
if n!=1:raise SystemExit('Cache nao reconhecido. Nada alterado.')
with tempfile.TemporaryDirectory() as tmp:
    test=Path(tmp)/'app.mjs';test.write_text(app);subprocess.run(['node','--check',str(test)],check=True)
outputs={root/name:base64.b64decode(data) for name,data in PAYLOAD.items()}
outputs.update({p:app.encode(),index:html.encode(),swpath:sw.encode()})
backup=root/'.super-juca-backup'/datetime.now().strftime('%Y%m%d-%H%M%S-%f')
for path in outputs:
    if path.exists():
        target=backup/path.relative_to(root);target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(path,target)
for path,data in outputs.items():path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(data)
print('Super Juca incluido com tres enderecos, selecao de loja, zoom, compartilhar e favoritos.')
print('Modo de teste: o encarte permanece visivel apos a validade. Backup: '+str(backup))
